<script setup lang="ts">
import {computed,onUnmounted,ref} from 'vue';
import {Plus,Minus,Maximize2,Trash2,Copy,Grip,ArrowRight,Undo2,Redo2,Unplug} from 'lucide-vue-next';
import {createNode,validateGraph,type WorkflowGraph,type WorkflowNode,type NodeType} from './workflow.ts';
import {listEnabledCatalog} from './modules/registry.ts';

const props=defineProps<{modelValue:WorkflowGraph}>();
const emit=defineEmits<{'update:modelValue':[graph:WorkflowGraph]}>();
const selected=ref(''),edgeSelected=ref(''),connecting=ref<{id:string;port:'out'|'yes'|'no'}|null>(null);
const zoom=ref(.8),offset=ref({x:32,y:60}),viewport=ref<HTMLElement>(),paletteSearch=ref('');
const past=ref<WorkflowGraph[]>([]),future=ref<WorkflowGraph[]>([]);
const graph=computed(()=>props.modelValue),node=computed(()=>graph.value.nodes.find(n=>n.id===selected.value));
const definition=computed(()=>listEnabledCatalog().find(n=>n.type===node.value?.type||n.id===node.value?.type));
const catalog=computed(()=>listEnabledCatalog().filter(n=>(n.label+n.description).includes(paletteSearch.value)));
const groups=computed(()=>[...new Set(catalog.value.map(n=>n.group))]);
const validation=computed(()=>validateGraph(graph.value));
let drag: {id?:string;x:number;y:number;ox:number;oy:number;before:WorkflowGraph}|undefined;
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
function update(next:WorkflowGraph,record=true){if(record){past.value.push(clone(graph.value));past.value=past.value.slice(-40);future.value=[];}emit('update:modelValue',next);}
function alter(fn:(next:WorkflowGraph)=>void){const next=clone(graph.value);fn(next);update(next);}
function undo(){const previous=past.value.pop();if(previous){future.value.push(clone(graph.value));emit('update:modelValue',previous);}}
function redo(){const next=future.value.pop();if(next){past.value.push(clone(graph.value));emit('update:modelValue',next);}}
function add(type:NodeType){const next=createNode(type,graph.value.nodes.length);next.id=crypto.randomUUID();next.position={x:Math.max(10,(80-offset.value.x)/zoom.value),y:Math.max(10,(80-offset.value.y)/zoom.value)+graph.value.nodes.length%4*35};alter(g=>g.nodes.push(next));selected.value=next.id;edgeSelected.value='';}
function select(id:string){selected.value=id;edgeSelected.value='';}
function remove(){if(node.value?.type==='input'||node.value?.type==='output')return;alter(g=>{g.nodes=g.nodes.filter(n=>n.id!==selected.value);g.edges=g.edges.filter(e=>e.source!==selected.value&&e.target!==selected.value&&e.id!==edgeSelected.value);});selected.value='';edgeSelected.value='';}
function duplicate(){if(!node.value||['input','output'].includes(node.value.type))return;const copy=clone(node.value);copy.id=crypto.randomUUID();copy.position.x+=35;copy.position.y+=50;alter(g=>g.nodes.push(copy));selected.value=copy.id;}
function setConfig(key:string,value:unknown){alter(g=>{g.nodes.find(n=>n.id===selected.value)!.config[key]=value;});}
function setEnabled(value:boolean){alter(g=>{g.nodes.find(n=>n.id===selected.value)!.enabled=value;});}
function port(id:string,which:'out'|'yes'|'no'){connecting.value={id,port:which};select(id);}
function connect(target:string){const source=connecting.value;if(!source||source.id===target)return;alter(g=>{if(!g.edges.some(e=>e.source===source.id&&e.target===target&&e.port===source.port))g.edges.push({id:crypto.randomUUID(),source:source.id,target,port:source.port});});connecting.value=null;}
function start(event:PointerEvent,id?:string){if(event.button!==0)return;if(!id&&(event.target!==event.currentTarget))return;event.preventDefault();if(id)select(id);else{selected.value='';edgeSelected.value='';}const n=graph.value.nodes.find(n=>n.id===id);drag={id,x:event.clientX,y:event.clientY,ox:n?.position.x??offset.value.x,oy:n?.position.y??offset.value.y,before:clone(graph.value)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end);}
function move(event:PointerEvent){if(!drag)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;if(drag.id){const next=clone(graph.value),n=next.nodes.find(n=>n.id===drag?.id)!;n.position={x:Math.max(0,drag.ox+dx/zoom.value),y:Math.max(0,drag.oy+dy/zoom.value)};emit('update:modelValue',next);}else offset.value={x:drag.ox+dx,y:drag.oy+dy};}
function end(){if(drag?.id&&JSON.stringify(drag.before)!==JSON.stringify(graph.value)){past.value.push(drag.before);future.value=[];}drag=undefined;window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);}
onUnmounted(end);
function arrange(){const order=validation.value.order.length?validation.value.order:graph.value.nodes.map(n=>n.id);alter(g=>{order.forEach((id,i)=>{const n=g.nodes.find(n=>n.id===id);if(n)n.position={x:(i%4)*285,y:Math.floor(i/4)*180};});});offset.value={x:25,y:60};zoom.value=.8;}
function fit(){if(!viewport.value||!graph.value.nodes.length)return;const nodes=graph.value.nodes,minX=Math.min(...nodes.map(n=>n.position.x)),minY=Math.min(...nodes.map(n=>n.position.y));const w=Math.max(...nodes.map(n=>n.position.x))+235-minX,h=Math.max(...nodes.map(n=>n.position.y))+140-minY;zoom.value=Math.max(.25,Math.min(1,(viewport.value.clientWidth-60)/w,(viewport.value.clientHeight-120)/h));offset.value={x:30-minX*zoom.value,y:70-minY*zoom.value};}
function curve(source:string,target:string,port?:string){const a=graph.value.nodes.find(n=>n.id===source),b=graph.value.nodes.find(n=>n.id===target);if(!a||!b)return '';const x=a.position.x+235,y=a.position.y+(port==='no'?107:75),tx=b.position.x,ty=b.position.y+75;return `M ${x} ${y} C ${x+75} ${y}, ${tx-75} ${ty}, ${tx} ${ty}`;}
function keyboard(event:KeyboardEvent){if((event.target as HTMLElement).closest('input,textarea,select'))return;if(event.key==='Escape'){connecting.value=null;selected.value='';edgeSelected.value='';}if(event.key==='Delete'){event.preventDefault();remove();}if(event.altKey&&node.value&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();alter(g=>{const n=g.nodes.find(n=>n.id===selected.value)!;n.position.x=Math.max(0,n.position.x+(event.key==='ArrowLeft'?-20:event.key==='ArrowRight'?20:0));n.position.y=Math.max(0,n.position.y+(event.key==='ArrowUp'?-20:event.key==='ArrowDown'?20:0));});}}
function nodeDef(n:WorkflowNode){return listEnabledCatalog().find(d=>d.type===n.type||d.id===n.type);}
defineExpose({fit});
</script>

<template>
<div class="flow-editor" @keydown="keyboard">
  <aside class="flow-palette" aria-label="管线模块库">
    <div class="flow-sidebar-title"><strong>模块库</strong><span>{{catalog.length}} 个模块</span></div>
    <input v-model="paletteSearch" aria-label="搜索管线模块" placeholder="搜索模块…"/>
    <section v-for="group in groups" :key="group"><h3>{{group}}</h3><button v-for="item in catalog.filter(n=>n.group===group)" :key="item.type" :title="item.description" @click="add(item.type)"><span class="flow-module-icon" aria-hidden="true">{{item.label.slice(0,1)}}</span><span>{{item.label}}</span><Plus :size="13"/></button></section>
    <p class="flow-palette-help">点击添加模块。连接输出圆点与目标输入圆点，决定执行顺序。</p>
  </aside>
  <div ref="viewport" class="flow-viewport" tabindex="0" aria-label="管线画布，拖动空白平移，选择节点后 Alt 加方向键移动" @pointerdown="start($event)">
    <div class="flow-canvas-toolbar"><span :class="validation.valid?'flow-valid':'flow-invalid'">{{validation.valid?'连线有效':'需要完善连线'}}</span><button @click="undo" :disabled="!past.length" title="撤销" aria-label="撤销"><Undo2 :size="16"/></button><button @click="redo" :disabled="!future.length" title="重做" aria-label="重做"><Redo2 :size="16"/></button><button @click="arrange">自动排布</button></div>
    <div class="flow-plane" :style="{transform:`translate(${offset.x}px,${offset.y}px) scale(${zoom})`}">
      <svg class="flow-wires" width="8000" height="8000" aria-label="模块连接"><defs><marker id="flow-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/></marker></defs><g v-for="edge in graph.edges" :key="edge.id"><path :d="curve(edge.source,edge.target,edge.port)" class="flow-wire-hit" tabindex="0" role="button" :aria-label="'选择连接 '+edge.source+' 到 '+edge.target" @click="edgeSelected=edge.id;selected=''" @keydown.enter="edgeSelected=edge.id;selected=''"/><path :d="curve(edge.source,edge.target,edge.port)" class="flow-wire" :class="{selected:edgeSelected===edge.id}" marker-end="url(#flow-arrow)"/></g></svg>
      <article v-for="n in graph.nodes" :key="n.id" class="flow-node" :class="{selected:n.id===selected,disabled:!n.enabled}" :style="{left:n.position.x+'px',top:n.position.y+'px'}" tabindex="0" :aria-label="nodeDef(n)?.label" @click="select(n.id)" @focus="select(n.id)">
        <div class="flow-node-grip" @pointerdown.stop="start($event,n.id)"><span class="flow-node-kind">{{nodeDef(n)?.group}}</span><Grip :size="15"/></div>
        <div class="flow-node-body"><strong>{{nodeDef(n)?.label}}</strong><p>{{nodeDef(n)?.description}}</p></div>
        <button v-if="n.type!=='input'" class="flow-port flow-port-in" :class="{connecting:!!connecting}" :aria-label="'连接到 '+nodeDef(n)?.label" @click.stop="connect(n.id)"></button>
        <template v-if="n.type!=='output'"><button class="flow-port flow-port-out" :class="{connecting:connecting?.id===n.id}" :aria-label="'从 '+nodeDef(n)?.label+' 连接'+(n.type==='filter'?'通过分支':'')" @click.stop="port(n.id,n.type==='filter'?'yes':'out')"></button><span v-if="n.type==='filter'" class="flow-port-label">是</span><button v-if="n.type==='filter'" class="flow-port flow-port-no" aria-label="连接条件不通过分支" @click.stop="port(n.id,'no')"></button><span v-if="n.type==='filter'" class="flow-port-label no">否</span></template>
      </article>
    </div>
    <div v-if="connecting" class="flow-connect-note">选择目标节点左侧圆点完成连接 <button @click="connecting=null">取消</button></div>
    <div class="flow-zoom"><button aria-label="缩小画布" @click="zoom=Math.max(.25,zoom-.1)"><Minus :size="16"/></button><span>{{Math.round(zoom*100)}}%</span><button aria-label="放大画布" @click="zoom=Math.min(1.5,zoom+.1)"><Plus :size="16"/></button><button aria-label="适应画布" @click="fit"><Maximize2 :size="16"/></button></div>
    <div class="flow-canvas-caption">{{graph.nodes.length}} 个节点 · {{graph.edges.length}} 条连接 · 拖动空白平移</div>
  </div>
  <aside class="flow-inspector" aria-label="模块配置">
    <template v-if="node&&definition"><div class="flow-sidebar-title"><strong>{{definition.label}}</strong><button class="icon-button" @click="duplicate" :disabled="['input','output'].includes(node.type)" aria-label="复制节点"><Copy :size="15"/></button></div><p>{{definition.description}}</p><label class="flow-check"><input type="checkbox" :checked="node.enabled" :disabled="['input','output'].includes(node.type)" @change="setEnabled(($event.target as HTMLInputElement).checked)"/>启用此模块</label>
      <label v-for="field in definition.fields" :key="field.key" class="flow-field"><span>{{field.label}}</span><textarea v-if="field.type==='textarea'" :value="String(node.config[field.key]??'')" rows="4" @change="setConfig(field.key,($event.target as HTMLTextAreaElement).value)"/><select v-else-if="field.type==='select'" :value="node.config[field.key]" @change="setConfig(field.key,($event.target as HTMLSelectElement).value)"><option v-for="option in field.options" :key="option.value" :value="option.value">{{option.label}}</option></select><input v-else-if="field.type==='checkbox'" type="checkbox" :checked="Boolean(node.config[field.key])" @change="setConfig(field.key,($event.target as HTMLInputElement).checked)"/><input v-else :type="field.type==='number'?'number':'text'" :value="String(node.config[field.key]??'')" @change="setConfig(field.key,field.type==='number'?Number(($event.target as HTMLInputElement).value):($event.target as HTMLInputElement).value)"/><small v-if="field.help">{{field.help}}</small></label>
      <div class="flow-node-connections"><strong>输出连接</strong><div v-for="edge in graph.edges.filter(e=>e.source===node!.id)" :key="edge.id"><span>{{edge.port==='yes'?'是 → ':edge.port==='no'?'否 → ':''}}{{nodeDef(graph.nodes.find(n=>n.id===edge.target)!)?.label}}</span><button aria-label="移除连接" @click="alter(g=>{g.edges=g.edges.filter(e=>e.id!==edge.id);})"><Unplug :size="14"/></button></div><template v-if="node.type!=='output'"><button class="subtle" @click="port(node.id,node.type==='filter'?'yes':'out')"><ArrowRight :size="14"/>连接下一模块</button><select v-if="connecting?.id===node.id" aria-label="选择连接目标" @change="connect(($event.target as HTMLSelectElement).value)"><option value="">选择目标…</option><option v-for="n in graph.nodes.filter(n=>n.id!==node!.id&&n.type!=='input')" :key="n.id" :value="n.id">{{nodeDef(n)?.label}} · {{graph.nodes.indexOf(n)+1}}</option></select></template></div>
      <button class="flow-remove" :disabled="['input','output'].includes(node.type)" @click="remove"><Trash2 :size="15"/>删除模块</button><small>删除后请重新连接上下游。Alt + 方向键可移动选中模块。</small>
    </template>
    <template v-else-if="edgeSelected"><h3>已选择连接</h3><p>连线决定模块执行顺序，画布位置只用于排布。</p><button class="subtle" @click="remove"><Unplug :size="15"/>移除这条连接</button></template>
    <template v-else><div class="flow-sidebar-title"><strong>流程检查</strong></div><p>选择一个模块配置规则。所有规则先生成差异，再提交执行。</p><div v-if="validation.valid" class="flow-inspector-note">流程连线已通过校验。接下来选择输入视频，预览每个节点的结果。</div><ul v-else class="flow-errors"><li v-for="message in validation.errors" :key="message">{{message}}</li></ul><div class="flow-inspector-note">条件模块支持「是 / 否」两条路径。多分支汇合使用「汇合」模块，冲突会进入复核。</div></template>
  </aside>
</div>
</template>

<style scoped>
.flow-editor{display:grid;grid-template-columns:190px minmax(300px,1fr) 260px;min-height:630px;border:1px solid var(--border);border-radius:12px;overflow:hidden;background:var(--surface)}
.flow-palette,.flow-inspector{padding:17px 14px;max-height:720px;overflow:auto;min-width:0}.flow-palette{border-right:1px solid var(--border)}.flow-inspector{border-left:1px solid var(--border)}.flow-sidebar-title{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:16px}.flow-sidebar-title>span{font-size:10px;color:var(--text-soft)}.flow-palette>input{width:100%;font-size:11px;padding:8px}.flow-palette section{margin-top:20px}.flow-palette h3{font-size:10px;color:var(--text-soft);margin:0 0 8px}.flow-palette section button{display:flex;justify-content:flex-start;text-align:left;width:100%;padding:8px 3px;font-size:11px;border-radius:5px}.flow-palette section button:hover{background:var(--accent-soft)}.flow-palette section button>svg{margin-left:auto}.flow-module-icon{display:grid;place-items:center;width:25px;height:25px;flex-shrink:0;border:1px solid var(--border);border-radius:6px;color:var(--accent);background:var(--surface-soft);font-size:10px}.flow-palette-help{font-size:10px;margin-top:20px}.flow-viewport{position:relative;overflow:hidden;min-height:630px;background-color:var(--surface-soft);background-image:radial-gradient(var(--border) 1px,transparent 1px);background-size:18px 18px;touch-action:none;isolation:isolate}.flow-plane{position:absolute;top:0;left:0;transform-origin:0 0;pointer-events:none}.flow-wires{position:absolute;top:0;left:0;overflow:visible;color:var(--accent);pointer-events:none}.flow-wire{fill:none;stroke:var(--accent-border);stroke-width:2.3;pointer-events:none}.flow-wire.selected{stroke:var(--accent);stroke-width:4}.flow-wire-hit{fill:none;stroke:transparent;stroke-width:18;pointer-events:stroke;cursor:pointer}.flow-wire-hit:focus{outline:none;stroke:var(--accent-soft)}.flow-node{position:absolute;width:235px;height:140px;border:1px solid var(--border);border-radius:9px;background:var(--surface);box-shadow:0 3px 8px #00000008;pointer-events:auto}.flow-node.selected{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}.flow-node.disabled{opacity:.5}.flow-node-grip{height:31px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 13px;cursor:grab;touch-action:none;color:var(--text-soft)}.flow-node-kind{font-size:10px}.flow-node-body{padding:13px 16px}.flow-node strong{font-size:13px}.flow-node p{font-size:10px;line-height:1.6;margin-top:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.flow-port{position:absolute;border:2px solid var(--accent);background:var(--surface);border-radius:50%;width:13px;height:13px;padding:0;top:69px}.flow-port-in{left:-7px}.flow-port-out,.flow-port-no{right:-7px}.flow-port-no{top:101px}.flow-port.connecting{background:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}.flow-port-label{position:absolute;right:12px;top:66px;font-size:10px;color:var(--accent);background:var(--surface)}.flow-port-label.no{top:99px}.flow-canvas-toolbar{position:absolute;inset:14px 14px auto;display:flex;align-items:center;gap:10px;z-index:2;pointer-events:none}.flow-canvas-toolbar>*{pointer-events:auto;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:7px;font-size:10px}.flow-canvas-toolbar>span{margin-right:auto}.flow-valid{color:var(--accent)}.flow-invalid{color:var(--warning-text)}.flow-zoom{display:flex;align-items:center;gap:8px;position:absolute;bottom:16px;right:16px;background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:4px;z-index:2;font-size:10px}.flow-zoom button{padding:5px}.flow-canvas-caption{position:absolute;bottom:20px;left:16px;font-size:9px;color:var(--text-soft);pointer-events:none}.flow-connect-note{position:absolute;left:15px;bottom:60px;background:var(--accent-soft);border:1px solid var(--accent);color:var(--text);font-size:11px;border-radius:6px;padding:10px;z-index:3}.flow-connect-note button{color:var(--accent);text-decoration:underline;margin-left:8px}.flow-inspector p,.flow-inspector small{font-size:10px;line-height:1.8;color:var(--text-soft)}.flow-inspector small{display:block;margin-top:5px}.flow-check{display:flex;align-items:center;gap:8px;font-size:11px;margin:18px 0}.flow-field{display:flex;flex-direction:column;align-items:flex-start;gap:7px;margin:15px 0;font-size:11px}.flow-field input:not([type=checkbox]),.flow-field textarea,.flow-field select{width:100%;padding:8px;font-size:11px}.flow-field textarea{resize:vertical;border:1px solid var(--border);border-radius:6px;font:inherit}.flow-node-connections{border-top:1px solid var(--border);margin-top:20px;padding-top:16px;font-size:10px}.flow-node-connections>div{display:flex;justify-content:space-between;padding:8px 0;gap:7px}.flow-node-connections>.subtle{margin-top:10px;font-size:10px;width:100%}.flow-node-connections select{max-width:100%;margin-top:8px}.flow-remove{color:var(--warning-text);margin-top:22px;font-size:11px;padding:8px 0}.flow-inspector-note{font-size:11px;line-height:1.9;border-top:1px solid var(--border);padding-top:18px;margin-top:18px;color:var(--text-soft)}.flow-errors{padding-left:15px;font-size:11px;line-height:1.9;color:var(--warning-text)}
@media(min-width:1700px){.flow-editor{grid-template-columns:210px minmax(450px,1fr) 290px;min-height:690px}.flow-viewport{min-height:690px}}
@media(max-width:1200px){.flow-editor{grid-template-columns:160px minmax(270px,1fr)}.flow-inspector{grid-column:1/-1;max-height:360px;border-left:0;border-top:1px solid var(--border)}.flow-viewport{min-height:530px}.flow-palette{max-height:530px}.flow-canvas-caption{display:none}}
@media(max-width:700px){.flow-editor{grid-template-columns:minmax(0,1fr)}.flow-palette{max-height:165px;border-right:0;border-bottom:1px solid var(--border)}.flow-palette section{display:inline-block;vertical-align:top;width:49%;margin-top:10px}.flow-palette-help{display:none}.flow-viewport{min-height:420px}.flow-sidebar-title{margin-bottom:9px}}
</style>
